format_code:
chip esp32

hardware {
    pin led: Output = 2
}

func wait_a() {
    var x: int = 1
    sleep(50ms)
}

func wait_b() {
    var x: int = 2
    sleep(100ms)
}

task worker {
    every 1s {
        wait_a()
        wait_b()
    }
}

system_graph.mermaid:
flowchart LR
    u_wait_a("wait_a()")
    s_sleep{{"sleep"}}
    u_wait_b("wait_b()")
    u_worker(("worker<br>↻ 1s"))
    u_wait_a -->|sleep| s_sleep
    u_wait_b -->|sleep| s_sleep
